/**
 * Payment Routes — Payment intent creation and status checks.
 * Generated by BackendForge
 */
const express = require('express');
const router = express.Router();
const paymentController = require('../controllers/payment.controller');
const { authenticate } = require('../middleware/auth.middleware');
const { paymentLimiter } = require('../middleware/rate-limiter.middleware');

router.use(authenticate);

// Create payment intent for an order
router.post('/create-intent', paymentLimiter, paymentController.createPaymentIntent);

// Get payment status for an order
router.get('/:orderId', paymentController.getPaymentStatus);

module.exports = router;
